/**
 * Filter profiles by specific gemstone category
 */
export function getBenchmarkProfilesByCategory(category: string): BenchmarkCaseStudy[] {
  return GEMSTONE_100_BENCHMARK_PROFILES.filter(
    p => p.gemstoneCategory?.toLowerCase() === category.toLowerCase()
  );
}

/**
 * Filter profiles by outcome (LIFT_POSITIVE vs DOWNFALL_NEGATIVE)
 */
export function getBenchmarkProfilesByOutcome(outcome: "LIFT_POSITIVE" | "DOWNFALL_NEGATIVE"): BenchmarkCaseStudy[] {
  return GEMSTONE_100_BENCHMARK_PROFILES.filter(p => p.outcomeType === outcome);
}

/**
 * Get profile by ID (1 to 100)
 */
export function getBenchmarkProfileById(id: number): BenchmarkCaseStudy | undefined {
  return GEMSTONE_100_BENCHMARK_PROFILES.find(p => p.id === id);
}

/**
 * Get statistical audit metrics across all 100 profiles
 */
export function getGemstoneAuditStatistics(): {
  total: number;
  lifts: number;
  downfalls: number;
  categoryBreakdown: Record<string, number>;
} {
  const lifts = GEMSTONE_100_BENCHMARK_PROFILES.filter(p => p.outcomeType === "LIFT_POSITIVE").length;
  const downfalls = GEMSTONE_100_BENCHMARK_PROFILES.filter(p => p.outcomeType === "DOWNFALL_NEGATIVE").length;
  const categoryBreakdown: Record<string, number> = {};

  for (const p of GEMSTONE_100_BENCHMARK_PROFILES) {
    const cat = p.gemstoneCategory || "Other";
    categoryBreakdown[cat] = (categoryBreakdown[cat] || 0) + 1;
  }

  return {
    total: GEMSTONE_100_BENCHMARK_PROFILES.length,
    lifts,
    downfalls,
    categoryBreakdown
  };
}
